-- Migración 0002. Separa estatus y tipos en tablas con PK integer
-- y cambia la PK de UNIDADES_TRANSPORTE de uuid a integer.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

CREATE TABLE "UNIDADES_ESTATUS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true
);

CREATE TABLE "UNIDADES_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true
);

INSERT INTO "UNIDADES_ESTATUS" ("CODIGO", "NOMBRE")
SELECT DISTINCT "ESTATUS", "ESTATUS"
FROM "UNIDADES_TRANSPORTE";

INSERT INTO "UNIDADES_TIPOS" ("CODIGO", "NOMBRE")
SELECT DISTINCT "TIPO", "TIPO"
FROM "UNIDADES_TRANSPORTE";

ALTER TABLE "UNIDADES_TRANSPORTE" DROP CONSTRAINT "UNIDADES_TRANSPORTE_TIPO_CHK";
ALTER TABLE "UNIDADES_TRANSPORTE" DROP CONSTRAINT "UNIDADES_TRANSPORTE_ESTATUS_CHK";
DROP INDEX "UNIDADES_TRANSPORTE_ESTATUS_IDX";

ALTER TABLE "UNIDADES_TRANSPORTE" ADD COLUMN "ID_TIPO" integer;
ALTER TABLE "UNIDADES_TRANSPORTE" ADD COLUMN "ID_ESTATUS" integer;

UPDATE "UNIDADES_TRANSPORTE" AS unidad
SET "ID_TIPO" = tipo."ID"
FROM "UNIDADES_TIPOS" AS tipo
WHERE tipo."CODIGO" = unidad."TIPO";

UPDATE "UNIDADES_TRANSPORTE" AS unidad
SET "ID_ESTATUS" = estatus."ID"
FROM "UNIDADES_ESTATUS" AS estatus
WHERE estatus."CODIGO" = unidad."ESTATUS";

ALTER TABLE "UNIDADES_TRANSPORTE" DROP COLUMN "TIPO";
ALTER TABLE "UNIDADES_TRANSPORTE" DROP COLUMN "ESTATUS";

ALTER TABLE "UNIDADES_TRANSPORTE" ALTER COLUMN "ID_TIPO" SET NOT NULL;
ALTER TABLE "UNIDADES_TRANSPORTE" ALTER COLUMN "ID_ESTATUS" SET NOT NULL;

ALTER TABLE "UNIDADES_TRANSPORTE"
  ADD CONSTRAINT "UNIDADES_TRANSPORTE_ID_TIPO_FK"
  FOREIGN KEY ("ID_TIPO") REFERENCES "UNIDADES_TIPOS" ("ID");

ALTER TABLE "UNIDADES_TRANSPORTE"
  ADD CONSTRAINT "UNIDADES_TRANSPORTE_ID_ESTATUS_FK"
  FOREIGN KEY ("ID_ESTATUS") REFERENCES "UNIDADES_ESTATUS" ("ID");

CREATE INDEX "UNIDADES_TRANSPORTE_ID_TIPO_IDX" ON "UNIDADES_TRANSPORTE" ("ID_TIPO");
CREATE INDEX "UNIDADES_TRANSPORTE_ID_ESTATUS_IDX" ON "UNIDADES_TRANSPORTE" ("ID_ESTATUS");

ALTER TABLE "UNIDADES_TRANSPORTE" DROP CONSTRAINT "UNIDADES_TRANSPORTE_pkey";
ALTER TABLE "UNIDADES_TRANSPORTE" DROP COLUMN "ID";
ALTER TABLE "UNIDADES_TRANSPORTE"
  ADD COLUMN "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY;
